// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load fonts at module level to guarantee render readiness
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type WordZoomEffectProps = Record<string, any>;

const getFontFamily = (name: string) => {
  if (name === "Inter") return interFamily;
  if (name === "Space Grotesk") return spaceGroteskFamily;
  return montserratFamily;
};

const WordZoomEffect: React.FC<WordZoomEffectProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 12,
  word1 = "Clarity",
  word1FontFamily = "Montserrat",
  word2 = "Consistency",
  word2FontFamily = "Montserrat",
  word3 = "Stronger support",
  word3FontFamily = "Montserrat",
  textColor = "#f8fafc",
  accentColor = "#38bdf8",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Keyframe Timing (strictly increasing array mapped to 0-1)
  const timepoints = [
    0, 0.10, 0.22, 0.30, 0.42, 0.50, 0.62, 0.70, 0.78, 0.86, 0.95, 1.0
  ].map((t) => t * durationInFrames);

  // Camera Path Interpolation Values - Adjusted to hold on the last word
  const camX_vals = [0, 600, 600, 0, 0, -600, -600, 0, 0, 0, 0, 0];
  const camY_vals = [0, 200, 200, 0, 0, -200, -200, 0, 0, 100, 100, 100];
  const camZ_vals = [-500, 400, 400, 200, 200, 1400, 1400, 900, 900, 2400, 2400, 2400];
  const camRX_vals = [5, 0, 0, 0, 0, 0, 0, -5, -5, 0, 0, 0];
  const camRY_vals = [-10, 0, 0, 0, 0, 0, 0, 10, 10, 0, 0, 0];

  const interpConfig = { 
    extrapolateRight: "clamp" as const, 
    extrapolateLeft: "clamp" as const,
    easing: Easing.inOut(Easing.ease) 
  };

  // Base Interpolations with easing for smoother motions
  const baseCamX = interpolate(frame, timepoints, camX_vals, interpConfig);
  const baseCamY = interpolate(frame, timepoints, camY_vals, interpConfig);
  const baseCamZ = interpolate(frame, timepoints, camZ_vals, interpConfig);
  const baseCamRotX = interpolate(frame, timepoints, camRX_vals, interpConfig);
  const baseCamRotY = interpolate(frame, timepoints, camRY_vals, interpConfig);

  // Drift offsets to soften linear keyframes and add continuous 3D floating feel
  const driftX = Math.sin(frame / 40) * 30;
  const driftY = Math.cos(frame / 35) * 30;
  const driftRotX = Math.sin(frame / 50) * 2;
  const driftRotY = Math.cos(frame / 45) * 2;

  // Final Camera Coordinates
  const finalCamX = baseCamX + driftX;
  const finalCamY = baseCamY + driftY;
  const finalCamZ = baseCamZ; 
  const finalCamRotX = baseCamRotX + driftRotX;
  const finalCamRotY = baseCamRotY + driftRotY;

  // Words Data Structure
  const words = useMemo(() => [
    { text: word1, x: -600, y: -200, z: 0, rx: 0, ry: 15, color: textColor, font: getFontFamily(word1FontFamily) },
    { text: word2, x: 600, y: 200, z: -1000, rx: 0, ry: -15, color: textColor, font: getFontFamily(word2FontFamily) },
    { text: word3, x: 0, y: -100, z: -2000, rx: 5, ry: 0, color: accentColor, font: getFontFamily(word3FontFamily) },
  ], [word1, word2, word3, textColor, accentColor, word1FontFamily, word2FontFamily, word3FontFamily]);

  // Perspective focal length
  const perspective = 1000;

  return (
    <AbsoluteFill style={{
      backgroundColor: bgColor,
      perspective: `${perspective}px`,
      overflow: "hidden",
    }}>
      {/* 3D World Container */}
      <div style={{
        width: "100%",
        height: "100%",
        position: "absolute",
        transformStyle: "preserve-3d",
        transform: `translate3d(${finalCamX}px, ${finalCamY}px, ${finalCamZ}px) rotateX(${finalCamRotX}deg) rotateY(${finalCamRotY}deg)`,
        transition: "none",
      }}>
        {/* 3D Words */}
        {words.map((w, i) => {
          const screenZ = w.z + finalCamZ;
          // Fade out strictly to prevent harsh camera clipping geometry
          const opacity = interpolate(screenZ, [perspective * 0.5, perspective * 0.75, perspective * 0.9], [1, 1, 0], { 
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp"
          });

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: `calc(50% + ${w.x}px)`,
                top: `calc(50% + ${w.y}px)`,
                transform: `translate3d(-50%, -50%, ${w.z}px) rotateX(${w.rx}deg) rotateY(${w.ry}deg)`,
                opacity,
                fontFamily: w.font,
                fontSize: "140px",
                fontWeight: 800,
                color: w.color,
                whiteSpace: "nowrap",
                textAlign: "center",
                textTransform: "uppercase",
                letterSpacing: "-0.02em",
                textShadow: `0px 15px 30px rgba(0, 0, 0, 0.7), 0px 5px 10px rgba(0, 0, 0, 0.4)`,
                transition: "none",
              }}
            >
              {w.text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default WordZoomEffect;